      WHEN (OLD.project_id IS NOT NEW.project_id OR OLD.archived_at IS NOT NEW.archived_at) BEGIN UPDATE search_revisions SET revision = revision + 1 WHERE kind = 'projects'; END;

CREATE TRIGGER IF NOT EXISTS search_revision_projects_projects_insert AFTER INSERT ON projects
      BEGIN UPDATE search_revisions SET revision = revision + 1 WHERE kind = 'projects'; END;

CREATE TRIGGER IF NOT EXISTS search_revision_projects_projects_delete AFTER DELETE ON projects
      BEGIN UPDATE search_revisions SET revision = revision + 1 WHERE kind = 'projects'; END;

